prototipo_html:
```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Protótipo Navegável — exp03ef1b: Nina e a Notícia que Desapareceu</title>
  <style>
    /* ==========================================================================
       TOKENS CANÔNICOS WIREFRAME-CINZA (UNOORIA DESIGN SYSTEM)
       ========================================================================== */
    :root {
      --superficie-base: #FFFFFF;
      --superficie-elevada: #FAFAFA;
      --superficie-midia: #E0E0E0;
      --borda-padrao: #C7C7C7;
      --borda-foco: #1A1A1A;
      --texto-primario: #1A1A1A;
      --texto-secundario: #6B6B6B;
      --acao-primaria: #1A1A1A;
      --acao-secundaria: #EDEDED;

      /* Tokens da Casca de Revisão (ferramenta de inspeção humana) */
      --casca-fundo: #1E2022;
      --casca-painel: #282A2D;
      --casca-borda: #3A3D42;
      --casca-texto: #F0F2F5;
      --casca-mutado: #9CA3AF;
      --casca-destaque: #38BDF8;
      --casca-acento: #F59E0B;
      --casca-pico: #EF4444;
      --casca-aha: #10B981;
    }

    /* Reset e Layout Geral da Casca */
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: var(--casca-fundo);
      color: var(--casca-texto);
      height: 100vh;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    /* Barra Superior de Revisão */
    .casca-topo {
      height: 52px;
      background-color: var(--casca-painel);
      border-bottom: 1px solid var(--casca-borda);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 16px;
      flex-shrink: 0;
      z-index: 100;
    }

    .casca-topo-esq {
      display: flex;
      align-items: center;
      gap: 12px;
      min-width: 0;
    }

    .badge-missao {
      background-color: var(--casca-borda);
      color: var(--casca-destaque);
      font-size: 11px;
      font-weight: 700;
      padding: 4px 8px;
      border-radius: 4px;
      letter-spacing: 0.5px;
      white-space: nowrap;
    }

    .titulo-etapa-ativa {
      font-size: 14px;
      font-weight: 600;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .badge-beat {
      font-size: 10px;
      font-weight: 800;
      text-transform: uppercase;
      padding: 2px 6px;
      border-radius: 3px;
      letter-spacing: 0.5px;
    }

    .badge-beat.pico { background-color: var(--casca-pico); color: #FFF; }
    .badge-beat.aha { background-color: var(--casca-aha); color: #FFF; }
    .badge-beat.memoravel { background-color: var(--casca-acento); color: #111; }
    .badge-beat.latch { background-color: #6366F1; color: #FFF; }

    .casca-topo-dir {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-shrink: 0;
    }

    .contador-telas {
      font-size: 12px;
      color: var(--casca-mutado);
      font-variant-numeric: tabular-nums;
    }

    .btn-nav-casca {
      background-color: var(--casca-borda);
      color: var(--casca-texto);
      border: 1px solid transparent;
      padding: 6px 12px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 4px;
      transition: all 0.15s ease;
    }

    .btn-nav-casca:hover {
      background-color: #4B5158;
      border-color: var(--casca-destaque);
    }

    .btn-nav-casca:focus-visible {
      outline: 2px solid var(--casca-destaque);
      outline-offset: 1px;
    }

    /* Corpo Principal: Trilho + Palco + Painel */
    .casca-corpo {
      flex: 1;
      display: grid;
      grid-template-columns: 280px 1fr 380px;
      min-height: 0;
      min-width: 0;
      overflow: hidden;
    }

    /* Trilho de Telas (Esquerda) */
    .casca-trilho {
      background-color: var(--casca-painel);
      border-right: 1px solid var(--casca-borda);
      overflow-y: auto;
      overflow-x: hidden;
      padding: 12px 8px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .grupo-etapa-trilho {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .titulo-grupo-trilho {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      color: var(--casca-mutado);
      padding: 4px 8px;
      letter-spacing: 0.5px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .item-tela-trilho {
      background: transparent;
      border: 1px solid transparent;
      color: var(--casca-texto);
      text-align: left;
      padding: 6px 8px;
      border-radius: 4px;
      font-size: 12px;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      gap: 2px;
      transition: background 0.1s ease;
      min-width: 0;
    }

    .item-tela-trilho:hover {
      background-color: rgba(255, 255, 255, 0.05);
    }

    .item-tela-trilho.ativo {
      background-color: rgba(56, 189, 248, 0.15);
      border-color: var(--casca-destaque);
      color: #FFF;
    }

    .item-tela-trilho .id-tela {
      font-family: monospace;
      font-size: 11px;
      font-weight: 700;
      color: var(--casca-destaque);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .item-tela-trilho .estado-tela {
      font-size: 11px;
      color: var(--casca-mutado);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .item-tela-trilho.ativo .estado-tela {
      color: #E2E8F0;
    }

    /* Palco Central (Onde a tela é renderizada) */
    .casca-palco {
      background-color: #121314;
      overflow: auto;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 24px;
      position: relative;
      min-width: 0;
    }

    /* ==========================================================================
       REGRA DE OURO DA CASCA: UM QUADRO POR VEZ
       .quadro-tela:not(.tela-ativa) DEVE TER display: none !important;
       ========================================================================== */
    .quadro-tela:not(.tela-ativa) {
      display: none !important;
    }

    .quadro-tela.tela-ativa {
      display: flex;
      flex-direction: column;
      flex-shrink: 0;
    }

    /* Moldura de Simulação (Desktop Institucional ou Bancada Unoojornal) */
    .moldura-viewport {
      background-color: var(--superficie-base);
      color: var(--texto-primario);
      border: 8px solid #2B2D31;
      border-radius: 8px;
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    /* Dimensões canônicas declaradas na spec */
    .moldura-desktop-hub {
      width: 1024px;
      height: 640px;
    }

    .moldura-tablet-jornal {
      width: 960px;
      height: 600px;
    }

    .legenda-viewport {
      margin-top: 8px;
      font-size: 11px;
      color: var(--casca-mutado);
      text-align: center;
    }

    /* Painel Lateral da Etapa (Direita - 380px) */
    .casca-painel-etapa {
      background-color: var(--casca-painel);
      border-left: 1px solid var(--casca-borda);
      overflow-y: auto;
      overflow-x: hidden;
      padding: 20px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      min-width: 0;
    }

    .painel-cabecalho {
      border-bottom: 1px solid var(--casca-borda);
      padding-bottom: 12px;
    }

    .painel-etapa-tag {
      font-size: 11px;
      font-weight: 700;
      color: var(--casca-destaque);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .painel-etapa-titulo {
      font-size: 18px;
      font-weight: 700;
      margin-top: 4px;
      color: #FFF;
    }

    .painel-secao-rotulo {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      color: var(--casca-mutado);
      margin-bottom: 6px;
      letter-spacing: 0.5px;
    }

    .painel-texto-conteudo {
      font-size: 14px;
      line-height: 1.55;
      color: #D1D5DB;
      word-wrap: break-word;
      overflow-wrap: break-word;
    }

    .painel-texto-conteudo p {
      margin-bottom: 10px;
    }

    .painel-texto-conteudo strong {
      color: #FFF;
    }

    .painel-box-didatico {
      background-color: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--casca-borda);
      border-radius: 6px;
      padding: 12px;
      font-size: 13px;
      line-height: 1.45;
    }

    .painel-rodape-fonte {
      margin-top: auto;
      padding-top: 16px;
      border-top: 1px solid var(--casca-borda);
      font-size: 13px;
      color: var(--casca-mutado);
      font-style: italic;
    }

    /* Rodapé da Casca (Informações da Jornada) */
    .casca-rodape {
      height: 48px;
      background-color: var(--casca-painel);
      border-top: 1px solid var(--casca-borda);
      display: flex;
      align-items: center;
      padding: 0 16px;
      gap: 24px;
      font-size: 12px;
      flex-shrink: 0;
      overflow-x: hidden;
      white-space: nowrap;
    }

    .item-rodape {
      display: flex;
      align-items: center;
      gap: 6px;
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .item-rodape strong {
      color: var(--casca-mutado);
      font-weight: 600;
    }

    .item-rodape span {
      color: var(--casca-texto);
      overflow: hidden;
      text-overflow: ellipsis;
    }

    /* ==========================================================================
       ESTILOS INTERNOS DOS QUADROS (ESTRITAMENTE NOS 9 TOKENS WIREFRAME-CINZA)
       NENHUMA COR HEXADECIMAL FORA DE :root É PERMITIDA AQUI DENTRO
       ========================================================================== */
    .tela-conteudo {
      flex: 1;
      display: flex;
      flex-direction: column;
      height: 100%;
      background-color: var(--superficie-base);
      color: var(--texto-primario);
      overflow: hidden;
      position: relative;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    }

    /* Chrome do Unoojornal (App Clonado de Notícias) */
    .uj-topbar {
      height: 44px;
      background-color: var(--superficie-elevada);
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
