      border: 1px solid var(--borda-padrao);
      border-left: 4px solid var(--borda-foco);
      border-radius: 6px;
      padding: 10px 14px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      flex-shrink: 0;
    }

    .uj-speech-nina-corpo {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .uj-avatar-nina {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background-color: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      font-weight: 700;
      flex-shrink: 0;
    }

    .uj-speech-texto {
      font-size: 13px;
      line-height: 1.4;
      color: var(--texto-primario);
    }

    /* Botão de Áudio Acessível (Mínimo 64px de alvo ou botão integrado acessível) */
    .btn-audio-acessivel {
      width: 44px;
      height: 44px;
      min-width: 44px;
      min-height: 44px;
      border-radius: 50%;
      border: 1px solid var(--borda-padrao);
      background-color: var(--superficie-base);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .btn-audio-acessivel:focus-visible {
      outline: 2px solid var(--borda-foco);
    }

    /* Galeria de Matérias (ArticleCards) */
    .uj-grid-noticias {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      flex: 1;
      min-height: 0;
    }

    .uj-card-materia {
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 14px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 10px;
      position: relative;
    }

    .uj-card-materia.em-foco {
      border: 2px solid var(--borda-foco);
      background-color: var(--superficie-elevada);
    }

    .uj-materia-suporte-tag {
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      color: var(--texto-secundario);
      letter-spacing: 0.5px;
    }

    .uj-materia-manchete {
      font-family: Georgia, serif;
      font-size: 15px;
      font-weight: 700;
      line-height: 1.3;
      color: var(--texto-primario);
    }

    .uj-materia-previa {
      font-size: 12px;
      line-height: 1.4;
      color: var(--texto-secundario);
      flex: 1;
    }

    /* Botões Padrão Wireframe */
    .btn-wire {
      height: 38px;
      padding: 0 16px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 600;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      cursor: pointer;
      border: 1px solid var(--borda-padrao);
      background-color: var(--superficie-base);
      color: var(--texto-primario);
    }

    .btn-wire.primario {
      background-color: var(--acao-primaria);
      color: var(--superficie-base);
      border-color: var(--borda-foco);
    }

    .btn-wire.secundario {
      background-color: var(--acao-secundaria);
      color: var(--texto-primario);
      border-color: var(--borda-padrao);
    }

    .btn-wire.desabilitado {
      opacity: 0.5;
      cursor: not-allowed;
      background-color: var(--acao-secundaria);
      color: var(--texto-secundario);
      border-color: var(--borda-padrao);
    }

    .btn-wire:focus-visible {
      outline: 2px solid var(--borda-foco);
      outline-offset: 1px;
    }

    /* Leitor Expandido de Notícia (ArticleBody) */
    .uj-leitor-expandido {
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      height: 100%;
      overflow-y: auto;
    }

    .uj-leitor-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      border-bottom: 1px solid var(--borda-padrao);
      padding-bottom: 12px;
    }

    .uj-leitor-titulo {
      font-family: Georgia, serif;
      font-size: 22px;
      font-weight: 700;
      line-height: 1.25;
    }

    .uj-leitor-corpo {
      font-size: 15px;
      line-height: 1.6;
      color: var(--texto-primario);
    }

    .uj-destaque-trecho {
      border: 2px dashed var(--borda-foco);
      padding: 2px 6px;
      border-radius: 4px;
      background-color: var(--superficie-elevada);
      font-weight: 600;
    }

    /* Proposições Lógicas (Etapa 2) */
    .grid-comparativo-e2 {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      flex: 1;
      min-height: 0;
    }

    .coluna-texto-e2 {
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 14px;
      overflow-y: auto;
      font-size: 13px;
      line-height: 1.5;
      background-color: var(--superficie-elevada);
    }

    .coluna-analise-e2 {
      display: flex;
      flex-direction: column;
      gap: 12px;
      overflow-y: auto;
    }

    .card-proposicao {
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 10px 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .card-proposicao-texto {
      font-size: 12px;
      font-weight: 500;
      line-height: 1.35;
    }

    .botoes-tripla-escolha {
      display: grid;
      grid-template-columns: 1fr 1fr 1.4fr;
      gap: 6px;
    }

    .btn-tripla {
      height: 32px;
      font-size: 11px;
      font-weight: 700;
      border: 1px solid var(--borda-padrao);
      background-color: var(--superficie-base);
      border-radius: 4px;
      cursor: pointer;
    }

    .btn-tripla.selecionado {
      background-color: var(--acao-primaria);
      color: var(--superficie-base);
      border-color: var(--borda-foco);
    }

    /* Card de Aposta / Latch (Etapa 2) */
    .card-aposta-latch {
      background-color: var(--superficie-elevada);
      border: 2px solid var(--borda-foco);
      border-radius: 6px;
      padding: 14px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .grupo-checkboxes-aposta {
      display: flex;
      justify-content: space-between;
      gap: 10px;
    }

    .checkbox-aposta-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      font-weight: 600;
      padding: 6px 10px;
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      flex: 1;
    }

    .checkbox-aposta-item.travado {
      background-color: var(--superficie-midia);
      opacity: 0.7;
      cursor: not-allowed;
    }

    /* Split-screen do Pico (Etapa 3) */
    .split-pico-container {
      display: grid;
      grid-template-columns: 1fr 1.2fr;
      gap: 16px;
      flex: 1;
      min-height: 0;
      align-items: stretch;
    }

    .card-split-hipotese {
      background-color: var(--superficie-elevada);
      border: 2px solid var(--borda-foco);
      border-radius: 6px;
      padding: 20px;
      display: flex;
      flex-direction: column;
      justify-content: center;
      gap: 16px;
      text-align: center;
    }

    .split-titulo-aposta {
      font-size: 16px;
      font-weight: 700;
      line-height: 1.4;
    }

    .split-linha-contraste {
      font-size: 13px;
      font-weight: 600;
      color: var(--texto-secundario);
      padding: 10px;
      background-color: var(--superficie-base);
      border: 1px dashed var(--borda-padrao);
      border-radius: 4px;
    }

    .split-coluna-feed {
      display: flex;
      flex-direction: column;
      gap: 12px;
      justify-content: center;
    }

    .feed-card-retornado {
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 12px 14px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .feed-card-ausente-vazio {
      height: 72px;
      border: 2px dashed var(--borda-padrao);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 700;
      color: var(--texto-secundario);
      background-color: var(--superficie-elevada);
    }

    /* Fichas Cadastrais / Gavetas de Metadados (Etapa 4) */
    .bancada-fichas-e4 {
      display: grid;
      grid-template-columns: 1fr 1.1fr;
      gap: 16px;
      flex: 1;
      min-height: 0;
    }

    .ficha-tecnica-card {
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .gaveta-metadado {
      background-color: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      padding: 8px 12px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .gaveta-metadado.vazia {
      border: 2px dashed var(--borda-foco);
      background-color: #FFF;
      animation: pulsoSuave 2s infinite ease-in-out;
    }

    @keyframes pulsoSuave {
      0%, 100% { border-color: var(--borda-foco); }
      50% { border-color: var(--borda-padrao); }
    }

    .gaveta-rotulo {
      font-size: 11px;
      font-weight: 700;
      color: var(--texto-secundario);
    }

    .gaveta-valor {
      font-size: 13px;
      font-weight: 600;
      color: var(--texto-primario);
    }

    /* Construtor Algorítmico / Esteira de Blocos (Etapa 5) */
    .esteira-blocos-container {
      display: grid;
      grid-template-columns: 1fr 1.3fr;
      gap: 16px;
      flex: 1;
      min-height: 0;
    }

    .bandeja-pecas {
      background-color: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .pista-encaixe {
      background-color: var(--superficie-base);
      border: 2px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .bloco-puzzle {
      background-color: var(--superficie-base);
      border: 2px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 10px 12px;
      font-size: 12px;
      font-weight: 700;
      display: flex;
      align-items: center;
      gap: 8px;
      cursor: grab;
      position: relative;
    }

    .bloco-puzzle.encaixado {
      border-color: var(--borda-foco);
      background-color: var(--superficie-elevada);
    }

    .bloco-puzzle.em-alerta {
      border: 3px solid var(--borda-foco);
      animation: pulsoAlerta 1.5s infinite;
    }

    @keyframes pulsoAlerta {
      0%, 100% { transform: scale(1); }
      50% { transform: scale(1.02); }
    }

    .engrenagem-rotacao-continua {
      width: 64px;
      height: 64px;
      border: 6px dashed var(--borda-foco);
      border-radius: 50%;
      margin: 12px auto;
      animation: girarInfinito 2s linear infinite;
    }

    @keyframes girarInfinito {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

    @media (prefers-reduced-motion: reduce) {
      .engrenagem-rotacao-continua {
        animation: none;
        border-style: solid;
      }
      .gaveta-metadado.vazia, .bloco-puzzle.em-alerta {
        animation: none;
      }
    }

    /* Enquete Editorial Canal B (Etapa 6) */
    .card-enquete-canal-b {
      background-color: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 20px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      max-width: 680px;
      margin: 0 auto;
    }

    .opcao-enquete-item {
      background-color: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 12px 14px;
      font-size: 13px;
      line-height: 1.45;
      cursor: pointer;
      display: flex;
      align-items: flex-start;
      gap: 10px;
    }

    .opcao-enquete-item.selecionada {
      border: 2px solid var(--borda-foco);
      background-color: var(--superficie-base);
      font-weight: 600;
    }

    /* Painel da Investigação Final (Grade 2x2) */
    .grade-painel-final {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      flex: 1;
    }

    .quadrante-final {
      background-color: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .quadrante-final-titulo {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      color: var(--texto-secundario);
    }

    .quadrante-final-corpo {
      font-size: 13px;
      line-height: 1.4;
      color: var(--texto-primario);
    }

    /* Marcador de Estado do Quadro (Linha de 11px obrigatória) */
    .marcador-estado-interno {
      height: 22px;
      background-color: var(--superficie-elevada);
      border-top: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 10px;
      font-size: 11px;
      color: var(--texto-secundario);
      flex-shrink: 0;
    }

    /* Placeholder geométrico com cruz proporcional */
    .placeholder-midia-x {
      background-color: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .placeholder-midia-x::before, .placeholder-midia-x::after {
      content: "";
      position: absolute;
      width: 140%;
      height: 1px;
      background-color: var(--borda-padrao);
    }

    .placeholder-midia-x::before { transform: rotate(25deg); }
    .placeholder-midia-x::after { transform: rotate(-25deg); }

    .placeholder-midia-x span {
      position: relative;
      z-index: 2;
      background-color: var(--superficie-base);
      padding: 2px 6px;
      font-size: 10px;
      color: var(--texto-secundario);
      border-radius: 2px;
      border: 1px solid var(--borda-padrao);
    }
  </style>
</head>
