      "E1-ALU-02": { acao: "Ler texto completo da notícia e tocar em Fechar Leitor.", muda: "Fecha a matéria e retorna para a galeria geral de reportagens do acervo." },
      "E2-ALU-01": { acao: "Marcar alternativa lógica de cada afirmação (V, F ou Não é possível saber).", muda: "Salva julgamento e libera a área inferior de compromisso investigativo." },
      "E2-ALU-02": { acao: "Marcar opções de previsão e clicar em Travar Previsão.", muda: "Trava checkboxes em cinza fosco (latch irreversível) e libera avanço para busca." },
      "E3-ALU-01": { acao: "Selecionar pílula Campo: Onde, definir valor 'pátio' e aplicar.", muda: "Aplica parâmetro e processa consulta indexada no banco de dados." },
      "E3-ALU-02": { acao: "Confrontar retorno do banco com aposta travada no split-screen.", muda: "Fixa evidência da matéria sumida e aguarda questionamento docente do Aha." },
