      "E5-ALU-01": { acao: "Organizar blocos lógicos na esteira e clicar em Simular Algoritmo.", muda: "Executa verificação da fila de fichas ou aciona alerta de laço infinito." },
      "E5-ALU-02": { acao: "Identificar falta da regra de término e clicar em Reorganizar Peças.", muda: "Interrompe rotação contínua e devolve peças para inserção do bloco FIM." },
